  // Centro de ayuda
  'support.headerTitle': 'Soporte',
  'support.title': 'Centro de ayuda',
  'support.intro':
    'Aquí encontrarás respuesta a lo que más nos preguntan. Si tu caso no está, escríbenos: contestamos a todos los mensajes.',
  'support.directContact': 'Contacto directo',
  'support.responseWindow': '48 horas hábiles',
  'support.responseTime': 'Respondemos en un plazo máximo de {plazo}. Atendemos en castellano.',
  'support.writeToSupport': 'Escribir a soporte',
  'support.writeToUsAt': 'Escríbenos a',
  'support.beforeWriting': 'Antes de escribir',
  'support.beforeWritingIntro': 'Con estos datos podemos resolverlo a la primera:',
  'support.include1': 'El correo con el que te registraste.',
  'support.include2': 'Qué esperabas que pasara y qué pasó en su lugar.',
  'support.include3': 'El teléfono o navegador que usas.',
  'support.include4': 'Una captura de pantalla, si el problema se ve.',
  'support.faq': 'Preguntas frecuentes',
  'support.documents': 'Documentos',
  'support.q1': 'Olvidé mi contraseña',
  'support.q1a1':
    'En la pantalla de acceso, toca «¿Olvidaste tu contraseña?» y escribe tu correo. Recibirás un enlace para crear una nueva.',
  'support.q1a2':
    'Si el correo no llega en unos minutos, revisa la carpeta de spam. Si aun así no aparece, escríbenos y restablecemos el acceso manualmente.',
  'support.q2': 'Cómo elimino mi cuenta y qué se borra',
  'support.q2a1':
    'Entra en Configuración, dentro de la app, y elige «Eliminar cuenta». Se te pedirá confirmación porque la acción no se puede deshacer.',
  'support.q2a2':
    'Se borran tu perfil y el contenido asociado: publicaciones, comentarios, historias y archivos subidos. Podemos conservar registros mínimos si una obligación legal o un reporte en curso lo exigen.',
  'support.q3': 'Mi historia desapareció',
  'support.q3a1':
    'Las historias se eliminan solas a las 24 horas de publicarse. No es un error: funcionan así a propósito, igual que en otras plataformas.',
  'support.q3a2': 'Las publicaciones del muro, en cambio, permanecen hasta que tú las borres.',
  'support.q4': 'No puedo subir una foto o un video',
  'support.q4a1':
    'Lo más habitual es el permiso. La app necesita acceso a tus fotos o a la cámara: actívalo en la configuración del teléfono → Z → Fotos (o Cámara). En iPhone el sistema solo pregunta una vez, así que si lo rechazaste antes hay que activarlo ahí a mano.',
  'support.q4a2':
    'También hay un límite de tamaño. Si el archivo lo supera, la app te dice cuánto pesa y cuánto se admite; con un video largo, recórtalo o comprímelo antes de subirlo.',
  'support.q4a3': 'Las historias admiten videos de hasta 15 segundos.',
  'support.q5': 'Cómo reporto una publicación o bloqueo a alguien',
  'support.q5a1':
    'Toca el icono «···» de la publicación y elige «Reportar publicación» o «Bloquear». Revisamos todos los reportes.',
  'support.q5a2':
    'Al bloquear a una persona dejas de ver su contenido y ella deja de ver el tuyo. Puedes deshacerlo desde su perfil.',
  'support.q5a3':
    'Si se trata de una situación grave o urgente, escríbenos directamente al correo de soporte y agrega una captura.',
  'support.q6': '¿Hay pagos dentro de la aplicación?',
  'support.q6a1':
    'No. Esta versión es una app de miembros: no vende nada ni pide datos de pago en ningún momento.',
  'support.q6a2':
    'El acceso al contenido formativo se gestiona fuera de la aplicación. Si tienes dudas sobre tu membresía, escríbenos.',
  'support.q7': 'Qué necesito para usar Z',
  'support.q7a1':
    'Un iPhone o un teléfono Android reciente, o cualquier navegador actualizado. Basta con una cuenta creada con tu correo electrónico.',
  'support.q7a2':
    'La app está en castellano, inglés y portugués; puedes cambiar el idioma en Configuración. Algunas funciones, como subir videos, necesitan conexión estable.',

